use neko_reliable::{AckRange,AckRanges,PathMtuLimits,IpVersion,Plpmtud,PlpmtudConfig,PmtuSendOutcome};
#[test] fn ack_ranges_generated_insertion_matches_canonical_batch() { for seed in 0..128u64 { let mut values=Vec::new(); let mut x=seed+1; for _ in 0..32 { x=x.wrapping_mul(1103515245).wrapping_add(12345); values.push(x%256); } let mut incremental=AckRanges::new(256).unwrap(); for n in &values { incremental.insert(*n).unwrap(); } let ranges=values.iter().map(|n|AckRange{start:*n,end:*n}).collect::<Vec<_>>(); let batch=AckRanges::from_ranges(256,&ranges).unwrap(); assert_eq!(incremental,batch,"seed={seed}"); } }
#[test] fn pmtud_probe_timeout_and_generation_reset_are_deterministic() { let cfg=PlpmtudConfig{base_mtu:1200,max_mtu:1500,attempts_per_size:1,max_probes:32,blackhole_threshold:3}; let mut p=Plpmtud::new(cfg,7).unwrap(); let first=p.start_probe().unwrap(); assert_eq!(p.on_emsgsize(first.size,Some(1300)),PmtuSendOutcome::RetryAt(1200)); p.reset_generation(8); assert_eq!((p.generation(),p.confirmed_mtu(),p.outstanding()),(8,1200,None)); let probe=p.start_probe().unwrap(); assert_eq!(p.acknowledge(probe.id,8,probe.size),Ok(false)); }
#[test] fn path_mtu_accounting_is_bounded_for_both_ip_versions() { let v4=PathMtuLimits::new(IpVersion::V4,1500,1400).unwrap(); let v6=PathMtuLimits::new(IpVersion::V6,1500,1400).unwrap(); assert_eq!(v4.max_datagram_bytes(1300),1272); assert_eq!(v6.max_datagram_bytes(1300),1252); assert!(PathMtuLimits::new(IpVersion::V6,1279,1500).is_none()); }
